def max_product(num_str: str, N: int, K: int) -> int:
    if not num_str or N <= 0 or K < 0 or K >= N - 1:
        raise ValueError("Invalid input parameters")

    num_list = [int(digit) for digit in num_str]

    # If K is 0, the maximum product is the number itself
    if K == 0:
        return int(''.join(map(str, num_list)))

    # If K is N-1, the maximum product is the product of all digits
    if K == N - 1:
        return int(''.join(map(str, num_list)))

    # Find the K largest digits to split the number string
    largest_digits = sorted(num_list, reverse=True)[:K+1]

    # Calculate the product of the largest digits
    max_product = 1
    for digit in largest_digits:
        max_product *= digit

    return max_product

