def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> int:
        total = 0
        for i, char in enumerate(isbn):
            if char == '-':
                continue
            if char == 'X':
                total += 10 * (10 - i)
            else:
                total += int(char) * (10 - i)
        return total % 11

    if len(isbn) != 13 or isbn[3] != '-' or isbn[7] != '-' or isbn[12] != '-':
        raise ValueError("Invalid ISBN format")

    isbn_digits = isbn.replace('-', '')
    if not isbn_digits[:-1].isdigit() or not (isbn_digits[-1].isdigit() or isbn_digits[-1] == 'X'):
        raise ValueError("Invalid ISBN digits")

    calculated_checksum = calculate_checksum(isbn_digits)
    if calculated_checksum == 0:
        return "Right"
    else:
        correct_checksum = 'X' if calculated_checksum == 1 else str(11 - calculated_checksum)
        return isbn[:-1] + correct_checksum

def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        raise ValueError("Invalid input: n must be greater than 0 and m must be non-negative")

    if m == 0:
        return 1

    # Initialize a 2D array to store the number of ways to pass the ball
    dp = [[0] * (m + 1) for _ in range(n)]

    # Base case: There is one way to be at the starting position after 0 passes
    for i in range(n):
        dp[i][0] = 1

    # Fill the dp array
    for j in range(1, m + 1):
        for i in range(n):
            dp[i][j] = dp[(i - 1) % n][j - 1] + dp[(i + 1) % n][j - 1]

    # The result is the number of ways to be at the starting position after m passes
    return dp[0][m]

def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Initialize a DP array where dp[i] represents the maximum importance value that can be achieved with a budget of i
    dp = [0] * (n + 1)

    # Iterate over each item
    for price, importance in items:
        # Update the DP array from the back to avoid using the same item multiple times
        for budget in range(n, price - 1, -1):
            dp[budget] = max(dp[budget], dp[budget - price] + importance)

    # The maximum importance value that can be achieved with the given budget is stored in dp[n]
    return dp[n]

def max_energy(beads):
    n = len(beads)
    if n < 3:
        return 0

    # Create a 2D array to store the maximum energy for subproblems
    dp = [[0] * n for _ in range(n)]

    # Iterate over all possible lengths of subproblems
    for length in range(2, n):
        for i in range(n - length):
            j = (i + length) % n
            for k in range(i + 1, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + beads[i] * beads[k] * beads[j])

    return dp[0][n - 1]

