def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i in range(n, -1, -1):
        coeff = coeffs[n - i]
        if coeff == 0:
            continue
        if i == 0:
            term = f"{abs(coeff)}"
        elif i == 1:
            if coeff == 1:
                term = "x"
            elif coeff == -1:
                term = "-x"
            else:
                term = f"{abs(coeff)}x"
        else:
            if coeff == 1:
                term = f"x^{i}"
            elif coeff == -1:
                term = f"-x^{i}"
            else:
                term = f"{abs(coeff)}x^{i}"
        if coeff < 0:
            term = "-" + term
        terms.append(term)
    return "".join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping and mapping[e] != o:
            return "Failed"
        mapping[e] = o

    if len(mapping) != len(set(mapping.values())):
        return "Failed"

    decoded_message = ''.join(mapping.get(c, c) for c in message)
    return decoded_message

def largest_prime_factor(n: int) -> int:
    if n <= 1:
        raise ValueError("Input must be a positive integer greater than 1.")

    # Start checking for factors from the smallest prime number, which is 2
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            # If i is a factor, n // i will be the other factor
            return n // i

    # If no factors are found, n itself is a prime number
    return n

def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x:
        return 0
    if k == 1:
        return 1
    return sum(count_partitions(n - i, k - 1, i) for i in range(x, n // k + 1))

def count_sequences(n: int, last: int, memo: dict) -> int:
    if n <= 0:
        return 0
    if last in memo:
        return memo[last]

    count = 0
    for i in range(1, last // 2 + 1):
        count += count_sequences(n - 1, i, memo)

    memo[last] = count
    return count

def count_coprime_pairs(x0: int, y0: int) -> int:
    if x0 <= 0 or y0 <= 0:
        raise ValueError("Both x0 and y0 must be positive integers.")

    if y0 % x0 != 0:
        return 0

    quotient = y0 // x0
    count = 0

    for a in range(1, quotient + 1):
        if quotient % a == 0:
            b = quotient // a
            if gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2

    return count

def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

