def generate_numbers(n, rules) -> int:
    if not isinstance(n, int) or not isinstance(rules, list):
        raise ValueError("Invalid input: n should be an integer and rules should be a list of tuples.")

    if not all(isinstance(rule, tuple) and len(rule) == 2 for rule in rules):
        raise ValueError("Invalid rules: each rule should be a tuple of two elements.")

    original_number = str(n)
    visited = set()
    queue = deque([original_number])

    while queue:
        current_number = queue.popleft()
        if current_number not in visited:
            visited.add(current_number)
            for i, digit in enumerate(current_number):
                for x, y in rules:
                    if int(digit) == x:
                        new_number = current_number[:i] + str(y) + current_number[i+1:]
                        queue.append(new_number)

    return len(visited)

