        raise ValueError("Invalid scoring system. Must be either 11 or 21 points.")

    if not points:
        return []

    scores = []
    player_score = 0
    opponent_score = 0

    for point in points:
        if point == 'W':
            player_score += 1
        elif point == 'L':
            opponent_score += 1
        else:
            raise ValueError("Invalid point character. Must be 'W' or 'L'.")

