def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Initialize a DP array where dp[i] represents the maximum value that can be achieved with i time
    dp = [0] * (T + 1)

    # Iterate over each herb
    for time, value in herbs:
        # Update the DP array from the back to avoid using the same herb multiple times
        for t in range(T, time - 1, -1):
            dp[t] = max(dp[t], dp[t - time] + value)

    # The maximum value that can be achieved with T time is stored in dp[T]
    return dp[T]

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7

    # Initialize a DP array where dp[i][j] represents the number of ways to arrange j pots using the first i types of flowers
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: There's one way to arrange 0 pots with 0 types of flowers
    dp[0][0] = 1

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(m + 1):
            for k in range(min(j, a[i-1]) + 1):
                dp[i][j] = (dp[i][j] + dp[i-1][j-k]) % MOD

    return dp[n][m]

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    key = key.upper()
    ciphertext = ciphertext.upper()
    plaintext = []

    for i in range(len(ciphertext)):
        key_char = key[i % len(key)]
        ciphertext_char = ciphertext[i]

        if 'A' <= key_char <= 'Z' and 'A' <= ciphertext_char <= 'Z':
            key_shift = ord(key_char) - ord('A')
            ciphertext_shift = ord(ciphertext_char) - ord('A')
            plaintext_char = chr((ciphertext_shift - key_shift) % 26 + ord('A'))
            plaintext.append(plaintext_char)
        else:
            raise ValueError("Key and ciphertext must consist only of alphabetic characters.")

    return ''.join(plaintext).lower()

def mod_inverse(a, b):
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    gcd, x, _ = extended_gcd(a, b)
    if gcd != 1:
        return None
    else:
        return x % b

