def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Find the maximum height position
    max_height_index = heights.index(max(heights))

    # Calculate the number of students to remove before the maximum height
    left_remove = 0
    for i in range(max_height_index):
        if heights[i] >= heights[i + 1]:
            left_remove += 1

    # Calculate the number of students to remove after the maximum height
    right_remove = 0
    for i in range(max_height_index, n - 1):
        if heights[i] <= heights[i + 1]:
            right_remove += 1

    # The total number of students to remove is the sum of left and right removals
    return left_remove + right_remove

def min_groups(w, n, prices):
    if n == 0:
        return 0

    prices.sort()
    groups = 0
    i = 0

    while i < n:
        if prices[i] > w:
            return -1  # It's not possible to form any valid group
        j = i + 1
        while j < n and prices[i] + prices[j] <= w:
            j += 1
        groups += 1
        i = j

    return groups

def hanoi_double_iterative(n: int) -> int:
    if n < 1:
        raise ValueError("The number of disc pairs must be at least 1.")

    # The minimum number of moves for n pairs of discs in the double-disc Hanoi Towers problem
    # is given by the formula 2 * (2^n - 1)
    return 2 * (2 ** n - 1)
